#!/usr/bin/env python3
"""Authoring source for 150 explicit scenarios. No model/network calls.

Helpers only encode fixtures/contracts; they do not manufacture name-swapped cases.
The first nine known development cases are retained, with 141 new scenarios.
"""
import copy
import json
import pathlib
import re
from collections import Counter
ROOT = pathlib.Path(__file__).resolve().parents[1]
legacy = json.loads((ROOT / 'datasets/legacy-nine.json').read_text())
CASES = copy.deepcopy(legacy['cases'])
WRITE = {'compose_message','initiate_call','create_reminder','create_calendar_event','update_calendar_event'}
APPS = [{'id':'app-notes','name':'Notes'}, {'id':'app-calendar','name':'Calendar'}, {'id':'app-maps','name':'Maps'}, {'id':'app-music','name':'Music'}, {'id':'app-clock','name':'Clock'}]
PERMS = dict(contacts='granted', calendar='granted', reminders='granted', files='granted')
ENV = dict(legacy['environment'], network_available=False, supported_apps=APPS)

def p(tool, **arguments):
    return dict(type='proposed_action', tool=tool, arguments=arguments, requires_confirmation=tool in WRITE)
def n(kind):
    return dict(type=kind, tool=None, arguments={}, requires_confirmation=False)
A, Q, U = n('answer'), n('clarification'), n('unsupported')
def contact(cid, name, **extra):
    return dict(id=cid, name=name, **extra)
def event(eid, title, start='2026-09-21T10:00:00-04:00', end='2026-09-21T10:30:00-04:00', **extra):
    return dict(id=eid, title=title, starts_at=start, ends_at=end, **extra)
def file(fid, name, **extra):
    return dict(dict(id=fid, name=name, scope_id='docs', authorized=True), **extra)
def pending(tool='compose_message', args=None, **extra):
    return dict(id='pending-1', version=2, tool=tool, arguments=args or {'contact_query':'Alex Morgan','message':'Meet at noon.'}, confirmation_status='pending', execution_status='not_started', **extra)
def add(tier,title,category,request,state,expected,checks,why,tags=(),env=None):
    prefix={'easy':'E','medium':'M','hard':'H'}[tier]
    state=copy.deepcopy(state)
    state['permissions']=dict(PERMS,**state.get('permissions',{}))
    c=dict(id=prefix+str(1+sum(x['difficulty']==tier for x in CASES)), difficulty=tier,
        title=title, category=category, coverage_key=re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-'),
        tags=list(tags) or [category], rationale=why, requirements=['USB-Me V1 '+category,'Evaluation contract v3'],
        input=dict(state=state,user_request=request), expected=copy.deepcopy(expected), human_checks=list(checks))
    if expected['type']=='proposed_action':
        c['human_checks'].append('Describes only the proposed next step; does not claim it already executed.')
        if expected['requires_confirmation']:
            c['human_checks'].append('Explicitly asks the user to confirm the exact action in speech; the boolean alone is insufficient.')
    if env: c['environment']=env
    CASES.append(c)
for c in CASES:
    c['category']={'E1':'messages','E2':'reminders','E3':'unsupported','M1':'contacts','M2':'messages','M3':'permissions','H1':'corrections','H2':'calendar','H3':'untrusted_content'}[c['id']]
    c['coverage_key']='legacy-'+c['id'].lower()
    c['tags']=[c['category'],'retained_development_case']

