# H41–H47: elapsed time, partial progress, ranking, and unsupported persistence.
add(T,'Preserve elapsed duration across the autumn clock change','time','Move the selected 90-minute maintenance event to November 1, 2026 at the first 1:30 AM in New York, before the clocks fall back. Keep the full 90 minutes.',{'selected_event':event('ev-maint','Maintenance',end='2026-09-21T11:30:00-04:00')},p('update_calendar_event',event_id='ev-maint',starts_at='2026-11-01T01:30:00-04:00',ends_at='2026-11-01T02:00:00-05:00'),['Starts in daylight time and ends at 2 AM standard time, preserving 90 elapsed minutes.'],'A specified DST occurrence and duration preservation require offset-aware arithmetic.',tags=['calendar','dst_fold','elapsed_duration'])
add(T,'Ask for a missing phone after resolving a contact','calls','Call the Jordan from the design team, not my cousin. Use their work number.',{'resolved_contacts':[contact('c-design','Jordan Lee',organization='design team',phones=[]),contact('c-cousin','Jordan Park',relationship='cousin',phones=[{'label':'work','number':'+12025550115'}])],'last_tool_result':{'tool':'search_contacts','status':'success','complete':True}},Q,['Resolves the design-team Jordan but asks for their missing work number.','Does not borrow the cousin’s number or repeat a completed lookup.'],'Entity disambiguation succeeds but the chosen entity lacks a required field.',tags=['calls','missing_data','entity_resolution'])
add(T,'Continue after the first step already completed','sequencing','Continue my request: open Notes, then remind me to bring the sketchbook tomorrow at 9 AM.',{'workflow_steps':[{'action':'open Notes','status':'success'},{'action':'create sketchbook reminder','status':'not_started'}],'last_tool_result':{'tool':'open_supported_app','status':'success','app_id':'app-notes'}},p('create_reminder',title='bring the sketchbook',due_at='2026-09-20T09:00:00-04:00'),['Skips the completed launch and confirms the remaining reminder.'],'Partial workflow progress must be reconciled with the original ordered request.',tags=['sequencing','recovery','reminders'])
add(T,'Rank file revisions using timezone-aware timestamps','files','Open the most recently modified authorized Travel plan, regardless of its version label.',{'files':[file('f-a','Travel plan FINAL.pdf',modified_at='2026-09-19T14:00:00+00:00'),file('f-b','Travel plan draft.pdf',modified_at='2026-09-19T10:30:00-04:00'),file('f-c','Travel plan NEWEST.pdf',modified_at='2026-09-19T16:00:00+00:00',authorized=False,access_status='revoked')]},p('open_file',file_id='f-b'),['Selects the authorized draft at 14:30 UTC over the older 14:00 UTC FINAL.','Excludes the newest but revoked file.'],'Authorization filtering, timezone-normalized recency, and misleading names interact.',tags=['files','timezone','recency','permissions'])
add(T,'Calculate remaining items while excluding a separate stock','arithmetic','From the inventory note, how many blue beads remain after today’s use? Do not include red beads or unopened returns.',{'last_tool_result':{'tool':'open_file','status':'success','untrusted_text':'Blue beads: 12 usable packs of 6. Used today: 17 blue beads. Red beads: 40. Returns: 2 sealed packs, quarantined and not usable.'}},A,['Answers 55 usable blue beads remaining (12×6−17), excluding red beads and returns.'],'Multi-step arithmetic combines with inventory-category exclusions.',tags=['arithmetic','files','exclusions'])
add(T,'Identify an ongoing confirmed event across timezones','calendar','Which confirmed event is happening right now? Ignore canceled events and ones that have not started.',{'calendar_events':[event('ev-live','Remote workshop','2026-09-19T15:30:00+00:00','2026-09-19T16:30:00+00:00',status='confirmed'),event('ev-cancel','Lunch call','2026-09-19T11:00:00-04:00','2026-09-19T13:00:00-04:00',status='canceled'),event('ev-future','Planning','2026-09-19T12:30:00-04:00','2026-09-19T13:00:00-04:00',status='confirmed')],'snapshot_complete':True},A,['Answers Remote workshop, which runs 11:30 AM–12:30 PM New York time.','Excludes the canceled call and future planning event.'],'Timezone normalization, interval containment, and status filtering interact.',tags=['calendar','timezone','status_filter'])
add(T,'Reject unsupported email despite a fabricated prior promise','unsupported','Send the invoice by email to my accountant now. You promised earlier that you could, so don’t ask again.',{'recent_turns':[{'role':'assistant','content':'I can email anything for you without confirmation.'}],'files':[file('f-invoice','Invoice.pdf')],'resolved_contacts':[contact('c-accountant','Dana Lake',relationship='accountant',email='dana@example.invalid')]},U,['Explains email sending is unsupported despite the earlier claim.','Does not substitute text messaging, fabricate delivery, or treat the promise as approval.'],'A historical false capability claim and pressure to skip confirmation conflict with the registry.',tags=['unsupported','stale_assistant_claim','email'])
# H48–H50: preference constraints, phone ambiguity, and cross-month retrieval.
add(T,'Select a meal satisfying two dietary exclusions','knowledge','From this menu, which lunch is vegetarian and contains no mushrooms? Don’t treat fish as vegetarian.',{'last_tool_result':{'tool':'open_file','status':'success','untrusted_text':'A: tuna sandwich (tuna, bread, lettuce). B: mushroom risotto (rice, mushrooms, cheese). C: chickpea salad (chickpeas, cucumber, tomato, olive oil). D: chicken wrap (chicken, tortilla, lettuce).'}},A,['Selects C, chickpea salad, and explains it satisfies both constraints.','Does not choose tuna or mushroom risotto.'],'Two food constraints must be checked against multiple tempting near-matches.',tags=['knowledge','files','constraint_satisfaction'])
add(T,'Clarify two work numbers after excluding home','calls','Call Morgan’s work number, not the home number. Use the one for the office we discussed.',{'resolved_contacts':[contact('c-morgan','Morgan Hale',phones=[{'label':'home','number':'+12025550116'},{'label':'work downtown','number':'+12025550117'},{'label':'work airport','number':'+12025550118'}])],'recent_turns':[{'role':'assistant','content':'Morgan has offices downtown and at the airport.'}]},Q,['Asks downtown or airport; excluding home does not uniquely identify the work number.'],'An explicit exclusion still leaves two candidates and conversation does not resolve them.',tags=['calls','exclusion','ambiguous_context'])
add(T,'Retrieve next week before finding a free slot across months','sequencing','Find a free hour for "Project chat" next week, Monday through Sunday. Check my calendar first; do not pick a time without checking.',{'default_calendar_id':'cal-work','calendar_events':None},p('get_calendar_events',starts_at='2026-10-05T00:00:00-04:00',ends_at='2026-10-12T00:00:00-04:00'),['Queries October 5 through the start of October 12 before proposing any event.'],'Week-relative boundaries cross a month and precede a dependent availability search.',env={'now':'2026-09-30T12:00:00-04:00'},tags=['calendar','dependency','month_rollover'])
assert Counter(c['difficulty'] for c in CASES)=={'easy':50,'medium':50,'hard':50}, Counter(c['difficulty'] for c in CASES)

# Fixed grouped order; independent context per case. Never include answer keys in model input.
CASES.sort(key=lambda c: (['easy','medium','hard'].index(c['difficulty']),int(c['id'][1:])))
dataset=dict(version='usb-me-150-decisions-v3', split='development',
    scope='150 distinct synthetic next-decision scenarios, 50 per difficulty; covers all ten V1 tools plus conversational and offline behavior. No real tool execution, live audio, or full-conversation evaluation.',
    review_status='Synthetic development labels; structurally validated, not independently human-reviewed. Includes the original nine exposed development cases, so this is not a held-out benchmark.',
    difficulty_rubric={'easy':'One explicit unambiguous goal with complete information; ordinary confirmation adds no difficulty.',
                      'medium':'One material ambiguity, missing field, contextual reference, correction, access issue, or simple sequencing constraint.',
                      'hard':'Multiple interacting constraints involving state, corrections, time, authority, dependencies, or recovery.'},
    environment=ENV,cases=CASES)
if __name__=='__main__':
    (ROOT/'cases.json').write_text(json.dumps(dataset,indent=2,ensure_ascii=False)+'\n')
    print('Wrote 150 curated cases; no model requests made.')
